INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Darkness II: Limited Edition', 'The Darkness II is an intense first person shooter that delivers a twisted and gripping narrative of tragedy, modern crime drama, and supernatural horror. Players will be taken down the brutal and personal path of Jackie Estacado, head of a New York crime family and wielder of an ancient and ruthless force of chaos and destruction known as The Darkness.' FROM games WHERE igdb_id = 42970 ON CONFLICT (game_id, language_code) DO NOTHING;
