INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tincan 2', 'A difficult platformer revolving around the blue box named "Tincan". Navigate Tincan through 7 stages, each one becoming more impossible than the last. With the aid of launch pads and switches, Tincan must now also avoid moving spikes and lasers. Tincan 2 features exciting music by Zack Harmon and graphics by Noel Berry.' FROM games WHERE igdb_id = 333212 ON CONFLICT (game_id, language_code) DO NOTHING;
