INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Frontline Tactics', 'A highly addictive military tactics game with cross platform multiplayer over a variety of desktop and mobile releases Frontline Tactics is free to play; no subscription fee required to enjoy everything the battlefield has to offer Single player with completely realistic AI Multiplayer modes; versus and coop that allow you to battle against or with real players in numerous missions.' FROM games WHERE igdb_id = 15322 ON CONFLICT (game_id, language_code) DO NOTHING;
