INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dead-or-alive-5-collectors-edition', 210707, '2012-09-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co50kb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scmijc.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dead or Alive 5: Collector''s Edition', 'In western territories the Collectors Edition includes: - A copy of Dead or Alive 5 (PlayStation 3 or Xbox 360) - A premium embossed steel case for packaging - A exclusive 92-page hardcover art book, with character renders, costume concept art and screenshots of stages. - A 20-track CD of the official game soundtrack. - A full-color wall poster, featuring most of the playable cast. - A code for the "Premium Swimsuit" Costume DLC for the full cast of playable female characters in the game. The Japanese Collectors Edition is slightly different, it includes: - A copy of Dead or Alive 5 (PlayStation 3 or Xbox 360) - A Premium embossed steel case for packaging - A exclusive hardcover art book - A CD of the official game soundtrack - 10 character postcards - 10 metal "character plates" - A code for "Premium Swimsuit Costumes" DLC for the full cast of playable female characters in the game.' FROM games WHERE igdb_id = 210707 ON CONFLICT (game_id, language_code) DO NOTHING;
