INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Indestructible', 'Grab the wheel, load up your guns, hit the road and leave the mangled wrecks of your victories in the dust as you battle to become the best in the exciting vehicular combat game Indestructible! Are you sick of all those boring, repetitive farming games? Then blow some %^&* up in this fully 3D, online multiplayer action game!' FROM games WHERE igdb_id = 344819 ON CONFLICT (game_id, language_code) DO NOTHING;
