INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shop Empire 2', 'The popular Shop Empire game sequel. With more booths, new facilities, a fun new parking system for cars and trains. But sadly also more clever thiefs that want to rob your shops! Build a bigger and better shopping mall, hire staff members to run the place smoothly. Shop Empire 2 is a detailed and free resource management game.' FROM games WHERE igdb_id = 328355 ON CONFLICT (game_id, language_code) DO NOTHING;
