INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hello Kitty World', 'Hello Kitty World is a real-time theme park simulation game created and developed by Sanrio (Nifty/Sanrio Wave Inc. ). Hello Kitty World was released on April 9, 2012 and is available to play on smart phones and iPad. In Hello Kitty World, players can attempt to develop and create their own Sanrio Amusement Parks. Players are then able to expand their businesses and grow their theme park from the ground up, through a series of goals.' FROM games WHERE igdb_id = 246935 ON CONFLICT (game_id, language_code) DO NOTHING;
