INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Miner Wars Arena', 'It is the year 2090. Our Solar System is in the aftermath of a total political breakdown. Humanity is fighting over resources in asteroids.Gameplay Take control of a mining spaceship, hack your way through asteroids, and crush your enemies in a fully destructible environment! Compete against AI-controlled bots or prepare for the ultimate death-match against another human player (2 players can play on 1 PC).' FROM games WHERE igdb_id = 16409 ON CONFLICT (game_id, language_code) DO NOTHING;
