INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ano Hi Mita Hana no Namae wo Boku-tachi ha Mada Shiranai', 'Ano Hi Mita Hana no Namae o Bokutachi wa Mada Shiranai is a visual novel developed by guyzware, based on the anime of the same name, it contains a branching story and multiple endings made just for the game. It also contains a communication mini-game where you can talk to a 3D model of Menma every day.' FROM games WHERE igdb_id = 122222 ON CONFLICT (game_id, language_code) DO NOTHING;
