INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ohr Oni', 'Ohr Oni is an Ao Oni spinoff game created with the OHRRPGCE (Official Hamster Republic Role Playing Game Creation Engine), a program that was pretty popular in the late 90s/early 00s pre-RPG Maker years. It is made in the style of late-80s Famicom games like Sweet Home and MOTHER, so if you’ve ever wanted to be chased around by a very cute, chunky 8-bit Oni, then this is your chance. The game is veeeeerrrry short (for players on their second playthrough, it can be cleared in less than 15 minutes) and has two endings.' FROM games WHERE igdb_id = 186620 ON CONFLICT (game_id, language_code) DO NOTHING;
