INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elkrone no Atelier: Dear for Otomate', 'Otomate-developed visual novel for the PlayStation Portable based on the turn-based RPG Atelier series by Gust. Meriela (a.k.a Meri) has inherited her grandmother''s workshop, and now it''s up to her to decide what to do with it. One day, a fairy called Popotto pops up at the front door, asking her to create a mysterious item—the Blue Wakaka. Neither the client nor the alchemist have ever seen it, but since the fairy is in no great hurry, he decides to lodge with Meri to help her out with item synthesis, ingredient collection, monster fights and finding her soul mate.' FROM games WHERE igdb_id = 58057 ON CONFLICT (game_id, language_code) DO NOTHING;
