INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kaleidoscope--1', 118688, '2012-06-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co723o.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8im3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kaleidoscope', 'Kaleidoscope consists of level-paintings, which differ in style and behavior, yet are controlled in a similar fashion with the help of just four buttons. The simplicity of the controls is overcompensated by the rich audio/visual experience presented within the game. Player’s responses to a constantly changing environment shall have an impact on both image and audio. This creates an illusion of a player being simultaneously a painter of the current image and a composer of the music heard. In addition to that, each level in Kaleidoscope has a clear defined goal, which opens up doors of an infinite synaesthesia world to the masses.' FROM games WHERE igdb_id = 118688 ON CONFLICT (game_id, language_code) DO NOTHING;
