INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Web Phantom Brave', 'Accompaning the adventures of Rini, Teal and Prinia, Web Phantom Brave is a sequel of Phantom Brave, taking place in the same universe of Ash and Marona, but 300 years after the events of the PS2 game. The game was only released on web browsers, being shut down a less than a year upon release, the game became in it''s entirely a lost media.' FROM games WHERE igdb_id = 366029 ON CONFLICT (game_id, language_code) DO NOTHING;
