INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chrono Tales', 'Chrono Tales is a Free 3D browser-based MMORPG. The new generation engine provides players with anime-styled 3D Graphics via browsers without huge downloads. Challenge immerse quests, tame mythological beasts, forge legendary gears and experience more! Chrono Tales is a free 3D browser-based MMORPG. The new generation engine provides players with anime-styled 3D graphics via browsers, without client download. Traveling through the time rift, players can explore in the fantasy world of Chrono Tales and save the realm from the resurgent evil. You can challenge immersive quest, forge legendary gear, tame mythological pets and experience much more mainstream MMO features in Chrono Tales.' FROM games WHERE igdb_id = 333574 ON CONFLICT (game_id, language_code) DO NOTHING;
