INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Little Pegasus: Kizuna DoPonyPachi', 'It''s My Little Pony in the style of a Cave shoot em up. Play as either Rainbow Dash or Fluttershy and fight against the hordes of evil to save Equestria! Careful though; the evil forces have taken control of your friends, and they now pilot enormous battleships!' FROM games WHERE igdb_id = 221574 ON CONFLICT (game_id, language_code) DO NOTHING;
