INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Parking Frenzy', 'Parking Frenzy brings the ultimate drive ‘n’ park experience! Get ready for hours of gameplay with 200+ levels, backed with 4 different weather situations: Autumn, Winter, Rain and Fog! Crazy huh? We’re not done just yet! Parking Frenzy 2.0 offers driving in 50 different, gorgeously designed cars, around two of the most beautiful cities in the world - New York City and London! Are you skilled enough to master the parking process? Will you be able to control your ride through realistic driving physics, and navigate it smoothly and precisely into the tiny parking spots?' FROM games WHERE igdb_id = 343786 ON CONFLICT (game_id, language_code) DO NOTHING;
