INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('burn-your-fat-with-me', 210716, '2012-08-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co50kp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/schz6f.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Burn Your Fat with Me!', '“Burn your fat with me!!” is a fitness app/dating sim that provides players with the motivation to work out through moé, a Japanese term describing that heart-melting feeling you get when you see an adorable female anime character. At its core, “Burn your fat with me!!” is a Japanese visual novel game akin to the “Phoenix Wright” or “Professor Layton” series. But instead of building a case or solving puzzles, the player advances the story by clearing fitness goals, such as performing 50 sit-ups in three minutes. The story revolves around the player’s relationship with childhood friend Mayu Uehara and is divided into 20 fully-voiced episodes*. Players train in real life by doing sit-ups, push-ups**, and squats with their iOS device while Mayu counts their repetitions and cheers them on. As the story advances, you become closer with Mayu but your fitness goals also become more demanding. Clearing the story may take several months of training, but stick with it and you’ll have something to show for in the real world as well!' FROM games WHERE igdb_id = 210716 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 210716 AND ge.slug = 'visual-novel' ON CONFLICT DO NOTHING;
