INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Call of Mini: Brawlers', 'A radiation leak at a nuclear power plant has the locals acting strange, eating brains and suchlike. You’re not the type to believe in stories about zombies, but you’re not gonna let some shambling freak snack on your brain, either! Grab a gun (or chainsaw or rocket launcher) and take back what’s left of your town!' FROM games WHERE igdb_id = 348485 ON CONFLICT (game_id, language_code) DO NOTHING;
