INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nayuta no Kiseki', 'Nayuta no Kiseki is an action role-playing game that was released on July 26th, 2012. The title has a completely new setting, new characters and even a new game system from previous "Kiseki" games. It is also the first game in the Kiseki series to drop the "Legend of Heroes" title.' FROM games WHERE igdb_id = 284431 ON CONFLICT (game_id, language_code) DO NOTHING;
