INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puyo Puyo!! 20th Anniversary: Mini Version', 'Puyo Puyo!! 20th Anniversary: Mini Version is a Puzzle game, developed and published by Sega, which was released in Japan in 2012. In Mini Version, you only have the option to just play as a single one. You play through eight stages, with each culminating in a Puyo Puyo battle against another character. At the end of each stage, you receive a rank ranging from F to S.' FROM games WHERE igdb_id = 86736 ON CONFLICT (game_id, language_code) DO NOTHING;
