INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arcane Shores', 'The island is quiet now. The king s scholars worked desperately to repair the Tome but their efforts were for naught. Will the days of prosperity ever return? That is for you to decide.' FROM games WHERE igdb_id = 343800 ON CONFLICT (game_id, language_code) DO NOTHING;
