INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Forget Me Not, My Love', '“We’re your fiances.” Three of your fiances show up after you wake up in the hospital! However, you can’t remember a single thing since you’ve lost all of your memories… Everything is a haze now due to you getting in an accident, and all you want to know is: who is your real fiance?' FROM games WHERE igdb_id = 238890 ON CONFLICT (game_id, language_code) DO NOTHING;
