INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pro Cycling Manager 2012', 'Prepare to live an iconic 2012 season by taking the lead of one of the 81 teams of the professional circuit. Real-time races, sponsors, riders’ contracts, training and equipment… It’s up to you to prove your worth as a manager, and lead your team to victory! With the new season planner, register your team to one of 180 official competitions, including prestigious races like the Tour de France 2012, la Vuelta, and the Ardennes Classics.' FROM games WHERE igdb_id = 10721 ON CONFLICT (game_id, language_code) DO NOTHING;
