INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Virtual City 2: Paradise Resort', 'Virtual City 2 is the follow-up to the SimCity style game Virtual City and this time is based in Florida, Alaska, Utah and Nevada. This time around, challenges include such things as building a Casino, Ski Resort and an Ice Hotel. The gameplay will be familiar to Virtual City fans but there''s not much innovation going on and only US users will appreciate the addition of more States.' FROM games WHERE igdb_id = 74320 ON CONFLICT (game_id, language_code) DO NOTHING;
