INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('protologic', 10430, '2012-06-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/zqf4mbpdd3e3bsvapjwm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ejviszi8ze8s2akiuibt.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Protologic', 'In this simple yet addictive game you will have to move marbles of various colors on a game board. The slots for the marbles are organized into pyramids; there is one main pyramid in the center and one or more supplemental pyramids around it. The game starts with the main pyramid fully filled with randomly shuffled marbles. Your goal is to move the marbles back and forth between the pyramids so that all marbles in the main pyramid are sorted by color (all marbles of the same color are on the same row). You can only move the marbles laying on top of other marbles (and don''t have any marbles on top of them) and you can only move them to another slot in the same or any other pyramid where they will be on top of other marbles as well. You can set up your own board by selecting the size of the main pyramid and the number and sizes of supplemental pyramids. You can also play a scenario (easy, medium, or hard) where you need to go through a sequence of levels with time or count limits.' FROM games WHERE igdb_id = 10430 ON CONFLICT (game_id, language_code) DO NOTHING;
