INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Presidents Quizzer', 'How much do you know about the Presidents of the United States? Play this fun, quick-fire quiz game to learn who they were and how they changed the world. Answer correctly before time runs out, or it''s game over! Gradually improve your knowledge of history, and prove to your friends that you''re the ultimate US patriot!' FROM games WHERE igdb_id = 89588 ON CONFLICT (game_id, language_code) DO NOTHING;
