INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Return To Booty Grotto', 'Swim through the mysterious Booty Grotto in search of treasure! A simple but challenging action game where you guide your intrepid fishy through a whole collection of varied and surprising levels, avoiding crazy traps and a bunch of loveable-yet-dangerous villains. Multiple paths through the game, multiple endings, secret exits, warps and bonus areas all await you if brave and skilful enough! Get the high score and complete every challenge to become a true Grotto master! The original game by Team Cherry (Hollow Knight)''s William Pellen' FROM games WHERE igdb_id = 363003 ON CONFLICT (game_id, language_code) DO NOTHING;
