INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Senjo no Valkyria Duel', 'Valkyria Chronicles D, also known as 戦場のヴァルキュリアドユーエル, or Senjou no Valkyria DUEL, is a mobile game released only in Japan. It was a free browser-based/iOS game, with radically different gameplay, focusing more on character management of war troops similar to sports team management simulations. It was released on July 26, 2012 and shut down on April 22, 2015.' FROM games WHERE igdb_id = 77367 ON CONFLICT (game_id, language_code) DO NOTHING;
