INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mass Effect 2: Ultimate Edition', 'They don’t expect you to survive. Entire human colonies on many worlds are vanishing. As Commander Shepard, you must assemble the galaxy’s deadliest team to save mankind against impossible odds. They call it a suicide mission, prove them wrong. The Mass Effect 2 Ultimate Edition includes Mass Effect 2 PLUS all the downloadable content packs for one great price. This includes Zaeed – The Price of Revenge, Kasumi – Stolen Memory, The Firewalker Pack, Overlord, Lair of the Shadow Broker, The Arrival, and more!' FROM games WHERE igdb_id = 99959 ON CONFLICT (game_id, language_code) DO NOTHING;
