INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jane''s Hotel: Family Hero', 'What would you do, if you had a chance to restore the famous chain of hotels that used to belong to your family? Decide faster... because soon, you would have the opportunity to help Jane to get back her heritage. Rule the hotels in France, England, Japan and on the Canaries. Explore the world''s latest tendencies in hotel business and challenge yourself with a greater goal.' FROM games WHERE igdb_id = 25382 ON CONFLICT (game_id, language_code) DO NOTHING;
