INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Valhalla', 'Valhalla is a zero-player role-playing game in which the player has no direct control of the character, and only chooses a name and a class. The character just wandering around, fighting random enemies, trading NPCs and collecting items. Upon levelling, the character recieves some random new equipment and a few stat bonuses.' FROM games WHERE igdb_id = 313350 ON CONFLICT (game_id, language_code) DO NOTHING;
