INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '7 Gates: The Path to Zamolxes', 'A long time ago, the Dacians asked their gods to hide their treasures. Now, you have been chosen to find the treasures and return them to your people in 7 Gates: The Path to Zamolxes! Pass through different temples and return home in this amazing Match 3 game. Embrace your destiny as the chosen one as you progress through tons of levels and find the incredible treasure in 7 gates: The Path to Zamolxes!' FROM games WHERE igdb_id = 52351 ON CONFLICT (game_id, language_code) DO NOTHING;
