INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gratuitous Tank Battles', 'Gratuitous Tank Battles (GTB) is a unique hybrid of tower-defense, strategy, simulation and RTS. Set in an alternate history timeline where World War I never ends, you are the commander of allied forces fighting right up to the year 2114, where Mechs and lasers are used alongside tanks and rifles. The war continues across Europe, with the allied commanders still locked into the optimistic patriotism of the 1900s.' FROM games WHERE igdb_id = 16334 ON CONFLICT (game_id, language_code) DO NOTHING;
