INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kingdom Island HD: Online Virtual World', 'Welcome to Kingdom Island HD - a virtual world in the palm of your hands! Connect on the go with your KingdomIsland account to meet new friends and socialize with thousands of other players worldwide! Customize your character, play games, and explore the island in a fun, safe, and exciting multiplayer environment! The possibilities are endless!' FROM games WHERE igdb_id = 175531 ON CONFLICT (game_id, language_code) DO NOTHING;
