INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Christmas Carol vs. The Ghost of Christmas Presents', 'Christmas Carol vs. The Ghost of Christmas Presents is an action arcade game. Guide Carol through the maze-like caverns to pick up all the Christmas presents while avoiding her enemies. Along the way, pick up candy and magical snowflakes that award you additional points and help you on your adventure.' FROM games WHERE igdb_id = 41466 ON CONFLICT (game_id, language_code) DO NOTHING;
