INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pokemon-tretta', 131497, '2012-07-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6n04.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scn0u0.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon Tretta', 'Pokémon Tretta is an arcade game developed by Takara Tomy A.R.T.S. and Marvelous AQL, which also developed the Pokémon Battrio arcade game. Officially announced on April 18, 2012, Pokémon Tretta was rolled out nationwide in Japan in early July, phasing out the majority of retired Battrio machines. The arcade machines became fully operational on July 14, 2012 with the release of the first set. The machines are also available in Taiwan in Traditional Chinese and in the Philippines, Indonesia, Malaysia, Singapore, Thailand, and Hong Kong in English. Like its predecessor, Pokémon Tretta focuses on three-on-three Pokémon battles that require special tiles, called Tretta, that depict one of the various Pokémon species in order to play. Unlike Battrio however, Tretta incorporates searching and capturing Pokémon in various locations. Pokémon caught in-game are dispensed for players to use in other battles, or to add to their collection.' FROM games WHERE igdb_id = 131497 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 131497 AND ge.slug = 'arcade' ON CONFLICT DO NOTHING;
