INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Memory Days', 'Memory Days is a sim dating game by Pacthesis. It was released in August, 2012. The game is a revamped version of Anime Sim Date 2.5, with the many of the same dateable characters, but with different gameplay and some changes in the graphics and the story lines. There are ten different endings.' FROM games WHERE igdb_id = 196255 ON CONFLICT (game_id, language_code) DO NOTHING;
