INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battleloot Adventure', 'Battleloot Adventure blends comedy and turn-based combat in a role-playing adventure. Key features include pledging your allegiance to one of four cities: The Stalwart Citadel, The Shady Docks, The Magnificent Academy and The Sparkling Tower. Recruit an assortment of adventurers, each with their own perks and unique skills. Carefully choose your 3 ideal adventurers to face each danger ahead. Upgrade and customize your characters and their abilities.' FROM games WHERE igdb_id = 186442 ON CONFLICT (game_id, language_code) DO NOTHING;
