INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fixation', 'Fixation is a prequel to The Company of Myself. It is a puzzle platformer that focuses on smoky mechanics, like activating a switch by bouncing a smoke ring off of a wall. It also aims to discuss the various habits that people form and the ways that people behave depending on who is nearby.' FROM games WHERE igdb_id = 316811 ON CONFLICT (game_id, language_code) DO NOTHING;
