INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zumba Fitness Core', 'Rock your core and dance your way to toned, sexy abs with Zumba Fitness Core, featuring 40 new songs and routines, more than 30 international dance styles from around the world and hot new choreography that''s designed to sculpt stronger abs through an exhilarating full body workout. Lose yourself in the music as celebrity Zumba instructors guide you through choreography set to contagious new Zumba fitness originals and a broader mix of smash hits from hot artists including Enrique Iglesias and Don Omar (full soundtrack to be announced at a future date).' FROM games WHERE igdb_id = 5307 ON CONFLICT (game_id, language_code) DO NOTHING;
