INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tilecan', 'This game was created as a part of the "0 hour game jam", a game jam taking place over the end of Daylight Savings Time, between 2 AM and 2 AM. Collect gems to increase your score while avoiding tiles the same color as you, but be careful - each gem will change your color!' FROM games WHERE igdb_id = 333223 ON CONFLICT (game_id, language_code) DO NOTHING;
