INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Clown Ball', 'Run away and join the circus! Swerve through mazes as you roll your ball past hammers, through tunnels and over balance beams. Try your acrobatic skills on the trampoline or dare to be fired from a circus cannon. You''ll love maneuvering through each level as you are challenged to solve puzzles and steer your ball toward the goal. Fans of marble rolling games like Super Monkey Ball and Neverball will love Clown Ball with fantastic tilt controls!' FROM games WHERE igdb_id = 368228 ON CONFLICT (game_id, language_code) DO NOTHING;
