INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Indiana Rodent', 'From the store page: "In this fast-paced platform game, you take the role of the Mouse With The Hat and go in search of the vaunted Lost Cheese. Traverse forests, deserts, and the Halls of Illusion; jump over hedgehogs, hitch a ride on a turtle, and evade vicious snakes - all for the reward of more cheese than you could ever eat, and what more could a mouse want?"' FROM games WHERE igdb_id = 57093 ON CONFLICT (game_id, language_code) DO NOTHING;
