INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mystery-case-files-shadow-lake-collectors-edition', 88269, '2012-11-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3spx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scd54x.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mystery Case Files: Shadow Lake - Collector''s Edition', 'Uncover the evil legend that haunts a forgotten town in Mystery Case Files®: Shadow Lake! In 1973, something wicked took over the town of Bitterford, Maine, after an unsuspecting inmate unearthed a mysterious object from beneath the prison floor. Years later, Bitterford lies in ruin. You must join forces with psychic Cassandra Williams, played by award-winning actress Lea Thompson, to investigate the events that led to the town''s destruction. Only you can expose the evil that lurks in the depths of Shadow Lake. But beware... What you discover may haunt you forever. This is a special Collector''s Edition release full of exclusive extras you won''t find in the standard version. As a bonus, Collector''s Edition purchases count toward three stamps on your Monthly Game Club Punch Card! The Collector''s Edition includes: Exclusive bonus gameplay Unlockable Morphing Objects Beautiful screensavers & wallpapers Exclusive behind-the-scenes video Dynamic casebook and integrated Strategy Guide' FROM games WHERE igdb_id = 88269 ON CONFLICT (game_id, language_code) DO NOTHING;
