INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Acatalepsy', 'Acatalepsy is a Japanese Yume Nikki fangame. Similar to most fangames, the player must explore Naoto''s dreams to collect effects and piece together his history and current self. The game''s readme warns squeamish viewers of "shocking" and "grotesque" content and color schemes. Much of the music used is disorienting and eerie, using an abstract, chiptune-esque style.' FROM games WHERE igdb_id = 150169 ON CONFLICT (game_id, language_code) DO NOTHING;
