INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pin-Kod. Poluchi patent pervym!', 'The twenty-third computer game based on the Smeshariki franchise and the second one that is part of the Pin-Code project. "Get a patent first!" gives everyone the opportunity to be an inventor and create an ingenious device themselves. The whole game is a continuous experiment; before each experiment there is a quiz, then a historical background, and then the experiment itself. You need to arrange the objects so that the experiment is successful, and after each experiment, a patent is issued.' FROM games WHERE igdb_id = 347819 ON CONFLICT (game_id, language_code) DO NOTHING;
