INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tsukumogami', 'Tsukumogami is the original Japanese version of 99 Spirits, a RPG/Puzzle game that revolves around the popular Japanese folklore of Tsukumogami, everyday objects coming alive on their 100th birthday. The Game Features an original battle system where players will have to puzzle out the true identity of the enemy before defeating them.' FROM games WHERE igdb_id = 16819 ON CONFLICT (game_id, language_code) DO NOTHING;
