INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('touhou-soujinengi-zansho-the-genius-of-sappheiros-shuumatsu', 210798, '2012-05-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co50pa.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/schzes.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Touhou Soujinengi Zansho: The Genius of Sappheiros - Shuumatsu', 'Shuumatsu (Weekend) features a heavy rebalancing of the rates for dropped items and Satori''s Learning, changes some of the recipes (with the most notable one being the recipe for the Kusanagi, which now only requires 5 Iron as opposed to 30), removes the feature that made you lose all of your "unsaved" items after getting wiped out in a dungeon, and adds a few new things such as a mini-map and an easy mode you can toggle on or off whenever you want. On easy mode, you deal more damage, take less damage, your status effects have a higher chance to work and the experience penalty on killing enemies at a lower level is reduced. You can also now refight the final boss whenever you want during the expansion, which means that Kagami''s Hyper Fang Crush is no longer permanently missable and can be learned by Satori whenever you want.' FROM games WHERE igdb_id = 210798 ON CONFLICT (game_id, language_code) DO NOTHING;
