INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Project Float', 'Join Buddy on his adventure to take down BluCo Science and save his town from the robot attack. Project Float is a puzzle based platformer with several RPG elements. You play as the child hero who stumbles upon an abandoned sphere who encourages him to help him defeat the robot overlord secretly in charge of this island. On your adventure you find several other robotic spheres who each give you, the player, a unique ability that will help you pass through obstacles.' FROM games WHERE igdb_id = 332206 ON CONFLICT (game_id, language_code) DO NOTHING;
