INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doomsday Preppers', 'Based on the popular National Geographic Channel TV show by the same name, Doomsday Preppers challenges you to prepare for a new (and even more fabulous) life below the ground. Design a multi-level dream bunker complete with everything you need for post-apocalyptic bliss, from a gym to a greenhouse to a disco bar! Flush out your subterranean palace one floor at a time while measuring and improving your survival skills along the way, so that you can extend your underground lifespan -- and keep on building!' FROM games WHERE igdb_id = 344291 ON CONFLICT (game_id, language_code) DO NOTHING;
