INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Geronimo Stilton: Return to the Kingdom of Fantasy', 'Geronimo Stilton, editor-in-chief of The Rodent’s Gazette, never thought he’d return to the Kingdom of Fantasy. But when the Queen of the Fairies sent him a letter asking for his help, he had the strangest feeling that a brand new adventure was just about to begin. Download Geronimo Stilton Return to the Kingdom of Fantasy The Videogame – and get ready for a spectacular story you’ll never forget. Compatible with PSP (PlayStationPortable) system only.' FROM games WHERE igdb_id = 42757 ON CONFLICT (game_id, language_code) DO NOTHING;
