INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Escape 4D', 'Dark Escape 4D is a fixed-gun arcade game for 2-players with a closed booth setup that has multiple built-in elements connected to the game. It has heart rate sensors in the gun handles, built-in air blowers in the front and back of the cabinet, rumble seats, surround sound speakers and a 3D visuals mode for use with the provided glasses. The game has 4 stages to choose from with a final 5th stage unlocked for clearing them in one session.' FROM games WHERE igdb_id = 62800 ON CONFLICT (game_id, language_code) DO NOTHING;
