INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Towers N'' Trolls', 'Fast paced fantasy tower defense... from the creators of Toy Soldiers and Baldur''s Gate: Dark Alliance! Defend your kingdom from invading troll hordes, with addictive quick-to-learn but difficult-to-master gameplay. Towers N'' Trolls combines fast-paced arcade action with quick-thinking strategy. The tower defense genre is updated for 21st Century mobile gaming with nail-biting moments where your fate teeters on a razor''s edge. No sitting and waiting for the enemy, they''re already at your door - it''s up to you to stop them! Towers N'' Trolls features beautifully hand-painted environments and playful, light-hearted monsters from the Age of Fantasy. Play across 11 worlds and 65 unique maps, including the Lonely Forest, Fertile Pastures, Snowy Forest, Underworld, Badlands, and the North.' FROM games WHERE igdb_id = 344892 ON CONFLICT (game_id, language_code) DO NOTHING;
