INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beach Buggy Blitz', 'Beach Buggy Blitz is built around an “infinite drive” mechanic that challenges you to drive as far as possible through lushly detailed, procedurally generated levels -- power-sliding through beaches and volcanoes, flying through the air off massive jumps, and smashing through totally destructible obstacles. Collect coins along the way to upgrade or paint your car, unlock new vehicles and drivers, even customize the game itself with new powerups and consumables.' FROM games WHERE igdb_id = 21622 ON CONFLICT (game_id, language_code) DO NOTHING;
