INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Who Am I?', 'Who am I is an immersive hidden object adventure of an epic scale. Take the role of an undercover agent investigating strange sci-fi incidents in the city as the threat of a weapon of mass destruction looms. Solve puzzles and seek out clues in over 70 detailed scenes. Find out who you really are to save the world!' FROM games WHERE igdb_id = 363827 ON CONFLICT (game_id, language_code) DO NOTHING;
