INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Web of Deceit: Black Widow - Collector''s Edition', 'Web of Deceit: Black Widow is a puzzle game where the player must search for hidden objects in scary, horror environments. Follow a trail of clues and dead husbands as you explore this once picturesque town now at the mercy of the Black Widow and her mechanical minions. What drives her lust for revenge? Where is the root of her strange power? Uncover the bizarre history - and mystery - of this little town. And track down the Black Widow in time to foil her devious plot for revenge! The collector''s edition includes; - Hours of bonus gameplay as Morgana! - Re-playable collection of puzzles - Concept art and stunning wallpaper - Brilliant soundtrack' FROM games WHERE igdb_id = 29240 ON CONFLICT (game_id, language_code) DO NOTHING;
