INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MathRat', 'The Math Rat teaches kids to count and do simple math. Through six levels of difficulty, the child is introduced to counting, adding, subtracting and larger/smaller than. Success is rewarded with medals and virtual candy, but watch out for the rat - He is sneaking around trying to steal your goodies and will if you don''t tap him quickly. Music can be turned off and game statistics may be viewed in the general device settings app. This app is kid-friendly: No ads, no external links, no in-app purchasing, no remote monitoring.' FROM games WHERE igdb_id = 370905 ON CONFLICT (game_id, language_code) DO NOTHING;
