INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('1-slash-2-summer', 98415, '2012-06-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coab3z.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scm3xu.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1/2 Summer', 'During the summer vacation, Kaname was asked to help out at his family''s inn in Tohoku. He had expected it to be a refreshing change from the sweltering heat in Tokyo, but when he arrived at the train station with his younger sister Kazuha, he was surprised to find that the town he once lived in, now have a huge school built in it. Boarding a crowded bus and traveling out of the city to Kusanagi Inn, he was relieved to see the familiar country scenery once again. But why are there schoolgirls in the inn? The owner told him that they were students from Jinza Gakuen in the city, but due to an incident they couldn’t stay in their dormitory, so she let them stay at the inn for the summer. That’s why he was needed there: there was a need for more staff to look after the girls. Furthermore, he had one more thing on his mind. The mischievous Zashiki-warashi that lived in the inn, because of whom he ends up returning to the countryside for good.' FROM games WHERE igdb_id = 98415 ON CONFLICT (game_id, language_code) DO NOTHING;
