INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hungry Cat', 'Hungry Cat: Puzzle Game Adventure - A Fun Brain-Teasing Journey! Ready to challenge your brain with a relaxing puzzle journey full of food, fun, and furry cuteness? Meet the adorable orange cat who’s always hungry - and always on the move! In Hungry Cat, a brain-teasing physics-based puzzle game, you’ll travel across the globe and solve clever block puzzles to roll delicious local food into the paws of your favorite kitty. Whether you love logic games, enjoy testing your quiz-solving skills, or just want a light, relaxing game with cute characters, Hungry Cat is your perfect choice.' FROM games WHERE igdb_id = 387690 ON CONFLICT (game_id, language_code) DO NOTHING;
