INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vampireville: haunted castle adventure', 'Vampireville is a hidden object, puzzle adventure game with three-dimensional characters and dynamic, addictive gameplay. You have to open secret doors, dig through the archives, catch bats, analyze blood samples, and play golf. You’ll also learn about vampires and ghosts, and meet a young witch who will predict your future!' FROM games WHERE igdb_id = 175295 ON CONFLICT (game_id, language_code) DO NOTHING;
