INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mars Defender Lite: 3D Asteroids', 'As a pilot of Mars Defense, you will fly the best spacecraft of the 22nd century as you defend the Inner System from attack and then engage the enemy to the Asteroid Belt and beyond.  Mars Defender provides a retro-styled overhead 3D view, in the style of classic Asteroids games. It features beautifully modelled planets, moons, asteroids, space stations and 12 different spaceships, all in full 3D.' FROM games WHERE igdb_id = 100060 ON CONFLICT (game_id, language_code) DO NOTHING;
