INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'In Your Arms Tonight', 'In Your Arms Tonight is an otome game for iOS and Android platforms. It is your third month of marriage and you have just discovered that your husband is cheating on you. Will you stay with him and work it out? Or will you try to find your happiness with someone else?' FROM games WHERE igdb_id = 63488 ON CONFLICT (game_id, language_code) DO NOTHING;
