INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dungeon-village', 19814, '2012-01-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2t3g.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arb65.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeon Village', 'Welcome to an epic RPG world in which the town you build can grow from humble hamlet into a mecca for the land''s most ambitious adventurers! The enterprising warriors that stop by your blossoming burg will defeat monsters and earn you money. Conquering dungeons and clearing out hordes of monsters will bag you loot to stock your shops. And if your hamlet flourishes, adventurers will want to set up house and settle down! Build training facilities like Combat Schools and Magic Labs to hone your heroic denizens'' skills and boost your village''s Popularity. The more faces that flock to your cause, the bigger the baddies you can beat! An all-new "Cauldron" feature also allows you to test your alchemic expertise. Toss items obtained from quests or shops into the Cauldron and your armory might receive a rare addition. No dungeon is too deep! Make your village the crown estate of this bold RPG narrative!' FROM games WHERE igdb_id = 19814 ON CONFLICT (game_id, language_code) DO NOTHING;
