INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Game Party Champions', 'Game Party Champions is the fifth and latest installment of the widely successful Game Party franchise and available exclusively for Wii U. The game’s fun, pick-up and play style will appeal to experienced and new gamers alike. Using the system’s innovative new GamePad, players tilt, turn and touch the controller to play arcade, sports and party games in entirely new ways. Eight Classic Games: Players can enjoy arcade, sports and party games such as Ping Pong and Skill Ball, and modern favorites such as Table Hockey and Hoop Shoot.' FROM games WHERE igdb_id = 4881 ON CONFLICT (game_id, language_code) DO NOTHING;
