INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spherical alliance', 'Spherical alliance is an old-school arcade action platformer inspired by the Arcade classic Solomon''s Key. It adds puzzle and strategy elements as well as some magic. It also includes a 2 player coop mode. If you like retro 2D platformers you should get Spherical alliance!' FROM games WHERE igdb_id = 166899 ON CONFLICT (game_id, language_code) DO NOTHING;
