INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grandma''s Garden', 'Join this charming dancing Grandma and all her silly veggies for fun adventures in the garden! She needs your help to match up the vegetables, identify letters, color the veggie, choose the right colors, and more. Grandma will teach you all about how things grow in real-live gardening videos. Plus, pick surprise goodies from Grandma''s bag! Find out why kids, parents, and teachers love Grandma''s Garden!' FROM games WHERE igdb_id = 99669 ON CONFLICT (game_id, language_code) DO NOTHING;
