INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Fantasy IV', 'FINAL FANTASY IV was the first title to introduce the Active Time Battle (ATB) system, which has become synonymous with the series. It also saw the introduction of the Augment system, which enabled the transfer of abilities from other characters and gave players an edge in battles. The remaster of Final Fantasy IV (2007) features a new Hard mode, autosaves, rebalancing, a new UI, and higher resolution visuals' FROM games WHERE igdb_id = 380634 ON CONFLICT (game_id, language_code) DO NOTHING;
