INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Armed and Gorgeous HD', 'Armed and Gorgeous HD by Digital Worlds A thrilling hack ''n'' slash-style game in which hoards of ignorant peasants, knights, and wizards wage war on a charming demoness in her own dungeon Exciting original comics await you at the end of every level! And with Ragdoll physics, fantastic animation, and comics-style graphics, you''ll never be bored! Conquer all the levels, beat all the bosses, reach the village and get revenge, gathering 11 types of weaponry and a variety of costumes for your heroine on the way!' FROM games WHERE igdb_id = 22335 ON CONFLICT (game_id, language_code) DO NOTHING;
