INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Toybox', 'Toybox is kinda like rubbing your head and patting your tummy at the same time. Shoot enemy toys on the left side of the screen to earn wooden blocks on the right. Then stack the blocks to explode stuff, power up your ship and earn extra lives. Each side affects the other, so master the interaction and survive as long as you can to get a high score.' FROM games WHERE igdb_id = 209423 ON CONFLICT (game_id, language_code) DO NOTHING;
