INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Table Football', 'Bring your own football stadium to life on any flat surface and play five-a-side football matches and tournaments wherever you are. Place all six AR Play Cards to create a pitch, two supporters'' stands and a scoreboard and start challenging friends via Ad Hoc Mode or taking on computer controlled opponents. Using touchscreen controls, you can play matches based on the classic tabletop football game; run, pass, shoot and even add swerve to your kicks with just a swipe of your finger.' FROM games WHERE igdb_id = 88895 ON CONFLICT (game_id, language_code) DO NOTHING;
