INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tower of Fortune', 'Tower of Fortune is a retro-style slot machine/RPG. You play as a retired hero and lived with daughter peacefully. Until one day, an unknown power from the mystic tower took her away. This force the hero to draw the sword again and fight for his daughter.' FROM games WHERE igdb_id = 130751 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 130751 AND p.igdb_id = 39 ON CONFLICT DO NOTHING;
