INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Car Town Streets', 'Build and race with all your favorite cars on Vehicle District Street. Rule the streets with your car and bring back the town''s former glory in its quest for Roxy. Form teams and compete in head-to-head racing battles for the ultimate victory. Build your car empire in Town today!' FROM games WHERE igdb_id = 281724 ON CONFLICT (game_id, language_code) DO NOTHING;
