INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Block Earth', 'Block Earth is an app for building, browsing and sharing worlds and mini-games. It works in a Minecraft-style world of blocks, with realistic animals and advanced shading. Download to explore thousands of readymade worlds and games, or build your own. Ride horses or even dragons, if you can land on one. Build a railway or a roller coaster to ride. To share worlds and games with the world, or to play with your friends on a wifi network, upgrade to premium inside the game.' FROM games WHERE igdb_id = 98860 ON CONFLICT (game_id, language_code) DO NOTHING;
