INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Smash Star', 'Many citizens of Kitty Town have disappeared. GK, the one and only kitty warrior in town, enlists the help of a star to find his friends. The path to Darkside isn''t an easy one, but it seems like that''s where all your friends have disappeared to. There''s likely more going on than meets the eye, so oil those cat dude muscles, do some warm-up push-ups and get going!' FROM games WHERE igdb_id = 188158 ON CONFLICT (game_id, language_code) DO NOTHING;
