INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bubble-bobble-4-cpc', 39080, '2012-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7rya.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/esylcuzik8s69fh4chgt.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bubble Bobble 4 CPC', 'Bubble Bobble is one of those games that are very difficult to dislike. It''s relentlessly charming and pathologically upbeat, with lead characters that are so instantly loveable if you dropped pictures of them on a desert island whose inhabitants had no contact with society you would be guaranteed a dragon-centric Cargo Cult within seven days. The original port of the game to the Amstrad CPC, however, was inarguably one of the poor relations of the franchise. It lacked the spirit that made the arcade version so great, and it is an unadulterated pleasure to play a new, shiny port of the game that shows what could have been done with more time and effort. Bubble Bobble for the CPC, abbreviated concisely by the developer into BB4CPC, underlines the excellence that can be achieved by one person working alone on a labour of love, for absolutely ages, without the pressures of working in a commercial development environment with deadlines, managers and budget restraints. The bangs and whistles, the panache and the cuteness, the occasional fiendish difficulty and the pathologically infectious theme tune are all there in spades.' FROM games WHERE igdb_id = 39080 ON CONFLICT (game_id, language_code) DO NOTHING;
