INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Reveal', 'Reveal is a short, experimental first person game that uses transforming space to explore perceptions of the human body. Take the lead in this physiologically-intense performance on a stage set for one. Watch as layers of knowledge and emotion slough off in swaths of paper and splinters of wood. Grab hold of your surroundings and rouse them to life. What you uncover will disturb, titillate, and reveal something unseen within yourself.' FROM games WHERE igdb_id = 128814 ON CONFLICT (game_id, language_code) DO NOTHING;
