INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('world-of-warcraft-mists-of-pandaria-collectors-edition', 136348, '2012-09-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5ye4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8i79.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World of Warcraft: Mists of Pandaria - Collector''s Edition', 'The World of Warcraft: Mists of Pandaria Collector''s Edition is a special box similar to previous collector''s edition boxes of World of Warcraft. It will be available at select retail locations. The following will be included: - World of Warcraft: Mists of Pandaria on CD-ROM and DVD-ROM. - The Art of Mists of Pandaria, 208 pages of art featuring never-before-seen artwork from early concepts to final 3D renderings. - An exclusive in-game mount: [Imperial Quilen]. - An exclusive in-game pet: [Lucky Quilen Cub]. - Diablo III - Banner sigil and accent. - StarCraft II - Portraits. - A behind-the-scenes DVD containing over an hour of directors'' commentary, insider interviews and developer roundtables that reveal how the continent of Pandaria came together from the combined efforts of artists, writers, designers, musicians and animators. - The collector''s edition soundtrack CD, containing music of Azeroth''s newest continent with twenty orchestral pieces. - A Mists of Pandaria mouse pad featuring Chen Stormstout, ready to rumble in true Brewmaster style.' FROM games WHERE igdb_id = 136348 ON CONFLICT (game_id, language_code) DO NOTHING;
