INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sesame Street: Elmo''s Musical Monsterpiece', 'Create a musical monsterpiece with Elmo and his Sesame Street friends. Play instruments, explore music and dance with Elmo, Abby Cadabby, Count von Count and the honkers as they travel through a music-themed land of wonder! Features - Learn about different styles of music as well as intrument and sound indentifaction. - Dance to various rhythyms and beats using simple Wii movments. - Use a second Wii remote to drop-in and assist when needed. - Monitor your child''s gameplay with the Parents Page tracking. - Game difficulty adapts to your child''s level.' FROM games WHERE igdb_id = 50935 ON CONFLICT (game_id, language_code) DO NOTHING;
