INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'City Siege Sniper', 'City Siege is back with a sniper edition! Use stealth to distract some baddies, or use your sniper rifle to pop a bullet in their head. Be sure to save the hostages with minimal casualties, and don''t forget to upgrade your guns! City Siege Sniper takes certain elements of a puzzle game and combines them with a shooter game across its 25 original and brand new levels.' FROM games WHERE igdb_id = 266850 ON CONFLICT (game_id, language_code) DO NOTHING;
