INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yu-Gi-Oh! 5D''s Duel Terminal 6', 'The Duel Terminal was designed by Konami to assist in introducing the then new Yu-Gi-Oh! 5D''s anime to new and existing players. The Duel Terminal itself looks like a traditional arcade machine and has a variety of game modes, using cards from the Yu-Gi-Oh! Official Card Game. Players can either use a Deck chosen by the system, or the Duelist can use his/her own cards.' FROM games WHERE igdb_id = 233293 ON CONFLICT (game_id, language_code) DO NOTHING;
