INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Inspiration Dave', 'Inspiration Dave is a 2012 flash platformer by Melos Han-Tani (co-creator of Anodyne series.) You control a character on a mission to find inspiration through musical notes throughout whatever world he lives in - via going through 33 small platforming stages, with three goals: Finish the stage, collect all 20 notes, and finish the stage 100% very quickly! Only finishing the stage is necessary. There are unlockable secrets for how many notes you collect and stages you finish quickly.' FROM games WHERE igdb_id = 274414 ON CONFLICT (game_id, language_code) DO NOTHING;
