INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heads Up! Hot Dogs', 'Assembled with the utmost care and attention under the supervision of highly-trained pixel craftsmen, Heads Up! Hot Dogs will tickle your fingertips as well as your taste buds with its rich tapestry of 2D flavors. Ultra-realistic, arcade-perfect visuals, stunning encased-meat sound effects and sizzling Space Age chiptunes combine to provide a culinary experience sure to satisfy even the most demanding gamer appetite. Travel the world as you drag and drop innocent wieners to safety, placing them ever-so-gently onto the noggins of befuddled passerby.' FROM games WHERE igdb_id = 175345 ON CONFLICT (game_id, language_code) DO NOTHING;
