INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oko', 'Oko is a hypnotising puzzle game that turns satellite images taken from the NASA database into a mesmerising journey around the Planet. The game''s rich otherworldly soundscapes are composed from recordings taken aboard space shuttles. The goal is to reconstruct an image by stopping rotating circles cut out from the image. For each level, the animated pieces draw increasingly complex patterns. The challenge is to be attentive to image juxtapositions in order to stop each circles movement at the right moment.' FROM games WHERE igdb_id = 128559 ON CONFLICT (game_id, language_code) DO NOTHING;
