INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Extreme Road Trip 2', 'Extreme Road Trip 2 is a mobile side-scrolling racing game where the objective is to travel as far as possible on a limited supply of fuel by picking up power-ups and doing stunts to increase your speed temporarily. In-game micro-transactions allow you to buy more power-ups, although they are also obtainable by leveling up your driver or finishing vehicle-specific missions.' FROM games WHERE igdb_id = 64275 ON CONFLICT (game_id, language_code) DO NOTHING;
