INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LotAtc', 'LotAtc is a complete simulation environment with client & server software which can connect with DCS World Simulator or work standalone with LotAtc Generator. It provides users to get an ATC/GCI view of the battle. Play the role of a tactical or air traffic controller and provide help to human pilots so that they better accomplish their missions, by radioing them a picture or guidance instructions!' FROM games WHERE igdb_id = 213717 ON CONFLICT (game_id, language_code) DO NOTHING;
