INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deer Drive Legends', '"Go for the ultimate trophy! Deer Drive: Legends takes you to the far corners of the earth where you will go after wild animals rarely seen by the human eye, some even believed to be extinct! Captured in rich, 3D environments, these animals are both elusive and quick! Stalk different species of elk, deer, big cats and more in the most exciting and realistic game available for Nintendo 3DS!"' FROM games WHERE igdb_id = 44012 ON CONFLICT (game_id, language_code) DO NOTHING;
