INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Agency of Anomalies: Mystic Hospital', 'Become a special agent and investigate a military hospital that hosted a variety of terrifying experiments in The Agency of Anomalies: Mystic Hospital! Discover the monstrosities that soldiers, doctors, and nurses have been transformed into, as you explore every single room of the hospital. Dive into this dark Hidden Object Puzzle Adventure game and stop a dimensional vortex from destroying the world!' FROM games WHERE igdb_id = 58045 ON CONFLICT (game_id, language_code) DO NOTHING;
