INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PuppetShow: Return to Joyville', 'This time traveling adventure takes you back to Joyville when Felicia was a small child. With the help of Felicia, try to stop the fire that incinerated her father’s theater. This fire horribly burned Felicia, and caused her to turn evil. By changing the past, Felicia hopes for a chance at redemption. Discover who the true villain is in this captivating adventure!' FROM games WHERE igdb_id = 140278 ON CONFLICT (game_id, language_code) DO NOTHING;
