INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Mysteries: The Soul Keeper', 'Charles Dexter Ward has summoned you to the island of Pawtuxet to stop a renegade spirit that is murdering the townspeople. The spirit is using human souls to become immortal, and you will be next if you cant stop him. Based on the novel by H.P. Lovecraft, this Hidden-Object Puzzle Adventure game will test your investigative skills as you solve the mysteries of Ward''s family and complete the ritual that will banish this evil spirit once and for all!' FROM games WHERE igdb_id = 57249 ON CONFLICT (game_id, language_code) DO NOTHING;
