INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('talking-tom-3-in-olympics', 315363, '2012-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8req.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sctro0.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Talking Tom 3 in Olympics', 'Talking Tom 3 in Olympics was a Chinese bootleg mobile game that was based on "Talking Tom" app that was developed by NanJing oooo3d in 2012. The game was mostly a clone of the regular Talking Tom app, which had the player talk to Tom and he would repeat back what the player had said. In addition to that, it also featured 2 mini-games, which were milk and study. The game notably contained the malware "Gooligan" within it, which installed rootkits and stole authentication tokens from Android devices to gain access to Google accounts, among many things. In 2013, the game was removed from the Google Play Store after the developers were sued by Outfit7 for copyright infringement.' FROM games WHERE igdb_id = 315363 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 315363 AND c.slug = 'nanjing-oooo3d' ON CONFLICT DO NOTHING;
