INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('toca-train', 108650, '2012-06-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6zsj.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Toca Train', 'All aboard? Time to get on Toca Train! Your kids are the train driver in this fun and friendly train simulator. The controls are intuitive and there are no written instructions. Just pull the levers, push the buttons and start exploring the island with your train! Toca Train is not a game - it''s a toy where you and your kids decide what you want to do. Where do passengers want to get off? At what stop should you unload the crate of pears? Your kids imagination is the only limitation! Just like a toy train set. As with all Toca Boca toys, there are no high scores, time limits or stressful music. Your kids can play with it however they want!' FROM games WHERE igdb_id = 108650 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 108650 AND c.slug = 'toca-boca' ON CONFLICT DO NOTHING;
