INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'To What End', 'Some cycles are meant to be broken - if you don''t, you might lose more than you realize. To What End questions our constant pursuit of extrinsic rewards, suggesting the best way to keep up with the Joneses is to stop chasing their world altogether.' FROM games WHERE igdb_id = 128731 ON CONFLICT (game_id, language_code) DO NOTHING;
