INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Living Legends: Ice Rose - Collector''s Edition', 'Novelist Edward Grand has found evidence of a terrible tragedy in the city of Rosemount and sets off to investigate in Living Legends: Ice Rose! Help Edward gather information for his new book and explore the Castle of Ice Queen in this incredible Hidden Object Puzzle Adventure game. Scour the frozen landscapes and thaw out important locations as you solve an intriguing mystery in Living Legends: Ice Rose!' FROM games WHERE igdb_id = 104704 ON CONFLICT (game_id, language_code) DO NOTHING;
