INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barn Runner: The Mayor''s New Dress', 'Mayor Marguerite DuChamp gets her turn in the spotlight (in more ways than one) in this Barn Runner take on the fairy tale The Emperor''s New Clothes. This game stars the mayor of Arc 19 and her best gal pal, The Chief. It''s done in a visual novel style with four possible endings in all. It was made for the July 2012 MAGS (Monthly Adventure Game Studio) contest.' FROM games WHERE igdb_id = 299082 ON CONFLICT (game_id, language_code) DO NOTHING;
