INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Logos Quiz', 'Logos Quiz is an entertaining game where you guess the logos of popular companies. Advance through levels of difficulty and strive for the highest score possible. The more logos you guess the more coins you will earn. If you get stuck and don''t know an answer, don''t give up! use the coins you gathered to get hints or remove unnecessary letters. If you are still stuck try asking your friends on Twitter or Facebook.' FROM games WHERE igdb_id = 254425 ON CONFLICT (game_id, language_code) DO NOTHING;
