INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zodiac Prophecies: The Serpent Bearer', 'Born under the rare 13th zodiac sign, Ophiuchus, Amy had no idea she was destined to save a magical world. Having already trapped children of the other 12 zodiac signs, the Dark Lord now has his sights on conquering our world as well. Amy must gather her courage to free the children''s souls and finally bring the Dark Lord''s tyranny to an end in Zodiac Prophecies: The Serpent Bearer.' FROM games WHERE igdb_id = 18894 ON CONFLICT (game_id, language_code) DO NOTHING;
