INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mutant Fridge Mayhem', 'Mutant Fridge Mayhem is an action game set in The Amazing World of Gumball universe where players battle mutated food across 30 levels. Players can switch between three playable characters - Gumball, Darwin, and Anais - each with unique abilities to combat the infected leftovers threatening Elmore. The game features character power-ups, including mustache transformations and tennis ball cannons, as players work to contain the mutation outbreak caused by spoiled jelly in the Watterson family refrigerator.' FROM games WHERE igdb_id = 87211 ON CONFLICT (game_id, language_code) DO NOTHING;
