INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Clay Jam', 'Save the land of Clay Jam from the fearsome Bully Beasts in this fun-packed action game. Guide Fat Pebble as he rolls down five weird and wonderful hills in a world made entirely from clay! Squash monsters on the way, and he''ll grow and grow and GROW! Get all the way to the bottom of the hill and meet the nasty Bully Beasts. Can you collect enough clay to free the monsters and save Clay Jam?!' FROM games WHERE igdb_id = 299181 ON CONFLICT (game_id, language_code) DO NOTHING;
