INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Diablo III: Collector''s Edition', 'This collector''s edition contains: - Diablo III - Behind the scenes (Blu-ray/DVD two-disc set) - Diablo III soundtrack CD - 208-page art book - Diablo skull and 4GB USB soulstone - A copy of Diablo II and the add-on Diablo II: Lord of Destruction located on the USB - Aesthetic Artifacts: Two special armor color dyes and glowing Tyrael''s Angelic Wings - Pet Fetish Shaman for World of Warcraft - Three Diablo-themed Battle.net portraits' FROM games WHERE igdb_id = 136279 ON CONFLICT (game_id, language_code) DO NOTHING;
