INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Patchwork', 'It''s a big day for Daniel - he''s about to test a teleportation device he''s been building for the last few years.  Will everything go as planned, resulting in a stunning breakthrough in modern science, or is he, as it so often happens in situations like this, going to end up in a parallel universe, where magic and fairies are pretty common, while cell phones and sneakers aren''t?' FROM games WHERE igdb_id = 138056 ON CONFLICT (game_id, language_code) DO NOTHING;
