INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Time Relics: Gears of Light', 'For hundreds of years, the clock tower at the edge of town has been a landmark and a tourist attraction. The tower itself appears to never age, and the small town''s inhabitants are prosperous and happy. Enter the Hands of Fate - a mysterious group whose objective is to keep the continuum of time running smoothly. You play as a member of the Hands of Fate determined to collect all the Gears of Light and return them to their rightful place in the tower thus restoring time to its rightful place - but, is it already too late?' FROM games WHERE igdb_id = 18895 ON CONFLICT (game_id, language_code) DO NOTHING;
