INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Platformer From Hell', 'Platformer from Hell combines gravity, switches, and platforming to create an experience unlike any other. Thrilling jumps, mind boggling gravity puzzles, and a pastrami sandwich in distress awaits Tie Guy in the abyss of PFH. Fulfill your primal greed by destroying Tie Guy repeatedly in his tragic quest for the root of all evil. Take control of Tie Guy on his journey to save his sandwich and traverse the depths in this passion inducing platformer.' FROM games WHERE igdb_id = 303213 ON CONFLICT (game_id, language_code) DO NOTHING;
