INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('virtual-goaltender', 86861, '2012-03-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/xssdj7wcgcrxkyrmhyaf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ifjaeaw65btscbo3ehjc.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Virtual Goaltender', 'Do you have what it takes to be a hockey goalie superstar? To strap on the pads, man the net and stop some pucks? Welcome to Virtual Goaltender, a heart pumpin’, adrenaline rushin’, reflex testin’, fast-paced ice hockey goalie game. -Challenge yourself in 70 levels of increasing difficulty from easy to insanely hard. -Make butterfly saves, kick saves, glove saves, blocker saves, skate saves and standup saves. -Includes many different challenges like one time shots, low and high shots, passing between shooters and intelligently aimed shots on goal. -Features fully 3D environments, lifelike goalie motions and realistic sound effects. -Hear the roar of the crowd as you make a save (or the boos of letting the puck slip through). -Choose from 5 different goalies, each with their own goaltending style. -Your choice of 5 different rinks, including a pro hockey arena or a frozen pond. -Over two dozen camera angles, including bird’s eye and goalie’s point of view. -Find out how fast your reflexes really are with the reaction time meter. -Amusing commentary praising your saves and mocking the shots you let through.' FROM games WHERE igdb_id = 86861 ON CONFLICT (game_id, language_code) DO NOTHING;
