INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('one-little-ghost', 279733, '2012-12-27', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/scpvas.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'One Little Ghost', 'If you ever felt sorry for the ghosts, the orphans they left behind, and wondered what would happen when Pac-Man became the ruling elite, then this is for you. Whilst researching to see if the ZX81 was capable of doing justice to an isometric game along the lines of Ant Attack! or KnightLore, Bob''s Stuff coded a program to display a single height map of tiles, and it looked a bit like a maze. Along with the code examples, he''d also been experimenting with the graphics required for such a game, and produced a cute little ghost. An idea then began to germinate... a maze, and some ghosts? Why not try a scrolling isometric Pac-Man? He''s still not sure if a full isometric game is possible (that''s for another day) but a scrolling flat one certainly is, and he''s really pleased with the results. It looks good, is fluid and responsive, and features most of the aspects of the original - including the (slightly bugged) A.I. and attack patterns. Having a ghost as the main character means that I''ve had to supplemented the concept of ''lives'' for ''spirit'' - I mean, a ghost doesn''t have a life, does it? - which introduces a slight twist on how you play the game.' FROM games WHERE igdb_id = 279733 ON CONFLICT (game_id, language_code) DO NOTHING;
