INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Make A Scene: Safari', 'Make a Scene Safari is a fun interactive game that engages children’s natural sense of creativity. It is aimed primarily at pre-school age children, but will provide hours of entertainment for children (and adults!) of all ages. Helping to develop vocabulary, fine motor skills, co-ordination and creative thinking, Make a Scene offers a great way for children to play and learn at the same time.' FROM games WHERE igdb_id = 99897 ON CONFLICT (game_id, language_code) DO NOTHING;
