INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Imagine: Babies 3D', 'Imagine is introducing a 3D baby simulation game where players can interact with the most true-to-life babies yet. As a babysitter, players travel the world caring for babies and helping them grow, keeping both the babies and their parents happy in order to build their reputation and ultimately open their own dream day care business. Experience the life of a successful babysitter with incredibly lifelike 3D visuals, animations and baby reactions!' FROM games WHERE igdb_id = 7951 ON CONFLICT (game_id, language_code) DO NOTHING;
