INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eureka Seven: AO Attack the Legend', 'Eureka Seven AO: Attack the Legend is a 3D mecha action game developed and published by Bandai Namco Entertainment for the PlayStation 3. Released as part of the Eureka Seven AO Hybrid Disc, the game allows players to pilot various LFO units from the series in multiple modes, including situation-based battles, missions, and challenges featuring characters from both Eureka Seven and Eureka Seven AO.' FROM games WHERE igdb_id = 64558 ON CONFLICT (game_id, language_code) DO NOTHING;
