INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dreamy Goat', 'Get ready to lose yourself inside surreal, psychedelic worlds and experience a relaxing atmosphere that is created with fantastic music, original gameplay and gorgeous artwork that you’ve never seen before. Every time Goat goes to sleep it sees beautiful dreams. But be careful - it is only a dream and you can wake up at any moment. This is a very unusual goat. It can jump through the air, travel between dreams on Super Whale and enjoys every moment of its journey. Also it likes to be filmed on camera and eat candy.' FROM games WHERE igdb_id = 174618 ON CONFLICT (game_id, language_code) DO NOTHING;
