INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slenderman''s Shadow', 'Slenderman''s Shadow is a survival horror game based on the Slenderman mythos. Explore 9 terrifying environments, including an old Hospice, an Elementary school, and a Carnival. Discover new areas, complete your mission, and survive the horrifying being pursuing you. Slenderman''s Shadow is a series of playable maps created (8th Oct 2012) by Marc Steene and Wray Burgess, and later (13th Jan 2013), as a full remake, a survival horror game, based on Slender: The Eight Pages by Parsec Productions.' FROM games WHERE igdb_id = 177282 ON CONFLICT (game_id, language_code) DO NOTHING;
