INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Medarot 7: Kabuto Version', 'Medarot 7 is the seventh numbered game in the Medarot franchise. Much like its predecessor Medarot DS, Medarot 7 is an RPG following the adventures of Azuma Amakura and his Medarot Metabee (in the Kabuto version) or Rokusho (in the Kuwagata version). Medarot 7 incorporates many of the gameplay changes made in Medarot DS, but does not function as a sequel. Rather, it completely ignores the events of Medarot DS and begins a new story using the same characters and places.' FROM games WHERE igdb_id = 138121 ON CONFLICT (game_id, language_code) DO NOTHING;
