INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('spell-rift', 174373, '2012-11-19', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/sce04h.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spell Rift', 'Spell Rift is a word-finding adventure. Navigate your way through the Rift, collecting words in your search for the fabled Well of Words. Along your journey you will encounter enchanting islands and intriguing gadgetry – bombs, locks, viruses, warpers, spinners, and more. Find words by dragging your finger over adjacent tiles. Let go to submit. After submission, the letters vanish and new tiles fall from above. Longer words earn more points as well as bonus tiles. Keep an eye on each level''s objective. You may need to find a certain number of words, a specific number of tiles, or perhaps just stay alive!' FROM games WHERE igdb_id = 174373 ON CONFLICT (game_id, language_code) DO NOTHING;
