INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sleepless Night', 'This is a short visual novel about Haru in which you team up with him to work on a school project. However, on this night something strange happens. Suddenly you’re locked inside your own room, and a dark power menaces your life! Can you find a way out of your room? Can you even survive this night? Pay attention to your environment, and you might have a chance to escape.' FROM games WHERE igdb_id = 172485 ON CONFLICT (game_id, language_code) DO NOTHING;
