INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tomb-raider-iii-adventures-of-lara-croft-collectors-edition', 43689, '2012-11-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3h9y.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scmgm6.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tomb Raider III: Adventures of Lara Croft - Collector''s Edition', 'In the Prologue, millions of years ago, a meteor struck the then tropical environments of Antarctica. It was first discovered by a tribe of ancient Polynesians who settled there and constructed a city in the meteorite crater. They worshipped the immense supernatural powers it appeared to hold, fashioning four artefacts out of the meteorite''s core material (which become the focus of the game). Shortly thereafter, the tribe laid witness to the deformed birth of their prophesied leader, born without a face, and fled Antarctica in fear of what the meteorite was capable of. In the present day, the ancient Polynesian city has been buried beneath snow and ice and RX Tech are excavating the site, investigating the meteorite. Led by Dr. Willard, the crew discovers remnants of the Polynesian city, ancient stone statues resembling the Easter Island Moai, and finds the grave of a man named Paul Caulfield of the HMS Beagle. When the game begins, Lara Croft is in India searching for a legendary stone in the ruins of an ancient temple once inhabited by the Infada tribe. She encounters Tony, an RX Tech employee who seems to be suffering from a severe bout of jungle fever. After parting ways, Tony remains one step ahead of Lara in their search for the stone, eventually finding it hidden deep within an underground cavern. After killing an oddly superhuman Tony, Lara takes the stone and exits. On her trek back to the Indian jungle, she is discovered by Dr. Willard.' FROM games WHERE igdb_id = 43689 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 43689 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
