INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('warlords-classic-strategy', 197718, '2012-06-10', NULL, NULL, NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Warlords Classic Strategy', 'The mission is simple – you should eliminate the other sides by capturing their cities. But victory is never easy - it can only be achieved by building massive armies, training and equipping mighty heroes, befriending legendary allies, and exploring the deep dark secrets hidden within Illuria''s ruins. So make your choice! Will you lead the Sirian Knights, the Gray Dwarves, the Storm Giants, the Orcs of Kor, the Elves of Elvallie, the Horse Lords, the mysterious Selentine Empire or the evil Lord Bane? Whomever you choose, fortune and glory await you! Detailed User Manual is included. We strongly recommend you to read it through carefully to refresh your memories and know about a few differences between this version and original game.' FROM games WHERE igdb_id = 197718 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 197718 AND p.igdb_id = 39 ON CONFLICT DO NOTHING;
