INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Craft Fighter', 'CraftFighter Game features many of your favorite Minecraft characters, monsters, and critters as playable fighter characters, each with their own suite of special moves! Built using the Craft Studio game-building engine – developed by Elisée – this highly polished game will entertain you for endless hours, even as you prove once and for all among your friends who is the superior fighter! Not too hot on the idea of fighting other players? Not a problem, the game features a single-player mode as well!' FROM games WHERE igdb_id = 139129 ON CONFLICT (game_id, language_code) DO NOTHING;
