INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega Man Christmas Carol Remix', 'In this remake of the original Flash game, controls have been improved, boss AI redone and made both fairer and more difficult, and the entire things been rebuilt from scratch with the Christmas Carol 2 engine! In addition there are achievements and 10 possible endings.' FROM games WHERE igdb_id = 209264 ON CONFLICT (game_id, language_code) DO NOTHING;
