INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tiny-racing', 101963, '2012-08-09', NULL, NULL, NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tiny Racing', 'Tiny Racing is a non-scrolling, top down online racing game. The gameplay is simple, but very hard to master. Race your car as fast as you can for 3 laps. Send challenges to your friends or random opponents, and beat each others race times during a 24 hour time slot. When the time is up, the challenge is locked, and points are rewarded. Friends race times, are downloaded as a ghost replay. The entire track is on screen, there is no scrolling. You have the complete overview and can take the corners very fast and tight. Tiny Racing is fast action, with relatively short race times. As you build skills, there are always milliseconds to cut off. Climb the leaderboards, where you can either compete in timetrial mode, or points from the challenge mode. Race against the top ranked racers, download their record ghost replays and beat their times. The first 2 cars and tracks are included. If you like the game, please support us and unlock more tracks and faster cars through in-app purchase. Thanks for your interest' FROM games WHERE igdb_id = 101963 ON CONFLICT (game_id, language_code) DO NOTHING;
