INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Just Dance: Greatest Hits', 'Just Dance: Greatest Hits is part of the Just Dance video game series published by Ubisoft. The game includes songs from Just Dance, Just Dance 2, Just Dance: Summer Party, and Just Dance 3, with 25 songs in the Wii PAL (Europe) counterpart (Best Of) and 35 songs in the NTSC (North America) Wii and Xbox 360 version (Greatest Hits). It is only available on the NTSC Wii and the Xbox 360.' FROM games WHERE igdb_id = 241441 ON CONFLICT (game_id, language_code) DO NOTHING;
