INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cross Hearts Arcadia', 'Researching an ancient ruin, Nirva hears a strange voice that leads him to an "egg" deep in the ruin which he takes home. In time, that egg turns into a curious fairy. The fairy named Tylt asks Nirva to travel to the Genesis Sanctuary together... A fantasy RPG where you set off from the floating continent Nirva calls home with his mysterious fairy Tylt on an adventure to find the Genesis Sanctuary!' FROM games WHERE igdb_id = 319834 ON CONFLICT (game_id, language_code) DO NOTHING;
