INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fireboy and Watergirl in the Ice Temple', 'Fireboy and Watergirl in The Ice Temple is a cooperative platformer and the 3rd entry in the Fireboy and Watergirl series. You navigate characters Fireboy and Watergirl - either alone or with a friend - through various puzzles. Fireboy can walk in lava, but not in water. Watergirl can walk in water, but not in lava. Turn levers, press buttons, push boxes, and more.' FROM games WHERE igdb_id = 122938 ON CONFLICT (game_id, language_code) DO NOTHING;
