INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wrestling Revolution Pro', 'Fully unlock the engine that sparked a Wrestling Revolution - saving your changes to over 300 characters across 9 rosters. For the first time in 2D, start your own career either side of the curtain - with wrestling and booking modes available in one epic game! Create your own star and embark on an endless career full of possibilities, as you attempt to make all the right moves backstage as well as in the ring. Or simply blow off steam in "Exhibition" matches of your own creation - where YOU make the rules, pick the players, and design the arena.' FROM games WHERE igdb_id = 91987 ON CONFLICT (game_id, language_code) DO NOTHING;
