INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Curiosity: What''s Inside the Cube?', 'Curiosity – What''s Inside the Cube? was an experimental video game by Peter Molyneux''s studio 22Cans. Originally called Curiosity, the game was later renamed to avoid confusion with the Mars rover. The social experiment ended on 26 May 2013 and was won by Bryan Henderson from Edinburgh, Scotland.' FROM games WHERE igdb_id = 23164 ON CONFLICT (game_id, language_code) DO NOTHING;
