INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Who Wants to Be a Millionaire: Special Editions', 'Get into the hot seat and play classic Millionaire for a chance to win a virtual million dollars! This all-new version of "Who Wants To Be A Millionaire" lets you play solo or challenge your friends. You keep gameplay fresh and fun with a constantly expanding library of question packs offering hundreds of new questions.' FROM games WHERE igdb_id = 94127 ON CONFLICT (game_id, language_code) DO NOTHING;
