INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('guide-the-light', 175514, '2012-11-22', NULL, NULL, NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guide the Light', 'Guide our intrepid hero through deadly mazes to find fame, fortune and glory! Captain Blake, the famous explorer, has discovered a lost pyramid filled with treasures of unimaginable value. The route through the pyramid is blocked by stone doors that stand between Blake and the treasure, opening only if beams of light fall on their receptor crystals. Help Captain Blake reach the heart of the pyramid by using mirrors and crystals to Guide the Light! Every chamber contains a unique puzzle and you''ll have to learn new skills to get through in one piece. Sometimes you''ll need to split and combine light colours, bounce light around mazes and even work against the clock to escape the pyramid''s fiendish traps.' FROM games WHERE igdb_id = 175514 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 175514 AND ge.slug = 'puzzle' ON CONFLICT DO NOTHING;
