INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Emily the Strange: Skate Strange', 'Emily The Strange: Skate Strange is the latest edition to the ever expanding universe of Emily the Strange - dive into the exciting world of skateboarding and explore over 36 levels located in the picturesque cities of Paris, Moscow, London and New York. Collect a wide variety of super charged power ups to ride in slow motion, skate upside down or even jump through portals that transport you instantly to a totally different location! Try out some crazy moves on your skateboard: play air guitar, perform a handstand or the famous ''ollie airwalk''! The extensive level editor brings endless fun: create your own levels and then skate them!' FROM games WHERE igdb_id = 157757 ON CONFLICT (game_id, language_code) DO NOTHING;
