INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Malice: Two Sisters', 'Help Victoria search for her missing sister, Emily, in Malice: Two Sisters. Emily''s last known whereabouts was Urami Island, the boarding school that both sisters attended many years ago. The island is abandoned these days and people whisper that it is cursed as well. Explore deserted ruins, discover the shocking history of Urami Island and save Emily in this gripping Hidden Object Puzzle Adventure!' FROM games WHERE igdb_id = 125641 ON CONFLICT (game_id, language_code) DO NOTHING;
