INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beloved', 'Beloved is a short game about love in all its forms. It’s about honesty, and making your way through a world full of obstacles.  This game isn’t meant to change your mind about anything – simply to make you think about the world, and maybe feel a little better about it.' FROM games WHERE igdb_id = 128688 ON CONFLICT (game_id, language_code) DO NOTHING;
