INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Koi wa Rule ni Shibararenai!', 'The protagonist is an ordinary high school girl who goes to Yuurin Secondary High School. Suddenly one day her uncle who is the school''s Board Chairman leaves his duties up to her as the next Chairman of the School Board. The power of the Board Chairman is great, they can change the school rules at any time. However at this school the approval of the Student Council is also needed. The five members of the Student Council appear in front of the protagonist. Sometimes fighting against them, sometimes cooperating with them, the protagonist has to overcome various problems while running the school. It''s time to start this year full of troubles!' FROM games WHERE igdb_id = 222630 ON CONFLICT (game_id, language_code) DO NOTHING;
