INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Misión en África', 'Mission in Africa was a Spanish educational interactive adventure that in order to advance you will have to answer basic Spanish language questions such as accents, punctuation marks and others. The story is about a secret agent called Zeta who will have to go to Africa to find out why so many trees and crops are drying up in an area where there were no earthquakes before.' FROM games WHERE igdb_id = 316782 ON CONFLICT (game_id, language_code) DO NOTHING;
