INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tales of the World: Dice Adventure', 'Tales of the World: Dice Adventure is a web browser-based board game in the Tales series released April 26, 2012 in Japan. The game is a role-playing and board game hybrid, where the player rolls virtual dice to determine how much a character moves across the board. Through the course of traversing the board, the player can form parties with other characters, experience story events, and participate in battles.' FROM games WHERE igdb_id = 294586 ON CONFLICT (game_id, language_code) DO NOTHING;
