INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Quick Fill Q', 'Quick Fill Q is a simple game where you have to fill the holes in the ground so the pink ball can keep rolling. When Q rolls past a certain distance, Q begins to speed up. When the game ends, the distance traveled by Q is recorded. Quick Fill Q is a non-stop, easy to learn puzzle game that provides hours of fun for the entire family.' FROM games WHERE igdb_id = 84836 ON CONFLICT (game_id, language_code) DO NOTHING;
