INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Horses 3D', 'The first authentic horse game for the Nintendo 3DS system, Horses 3D invites players to care for more than 15 realistic horses, ride them and train them for world-class performance. Horses 3D fully leverages the Nintendo 3DS features with the most realistic visuals for a horse game yet, including 3D horses, textures and beautiful environments, as well as StreetPass sharing and more.' FROM games WHERE igdb_id = 47637 ON CONFLICT (game_id, language_code) DO NOTHING;
