INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rabbids Invasion', 'Rabbids Invasion was a simulation social network game released by Ubisoft on April 3, 2012. The game (which was still in beta production throughout its course) was available for free as an Adobe Flash application for anybody who has an account on social networking site Facebook. On the 28th January 2013, the Rabbids Invasion Facebook page announced that the game was be closed on the 13th February 2013; the reason for this is currently unknown, but the name Rabbids Invasion had since been used as the title for an animated TV series which aired in August 2013.' FROM games WHERE igdb_id = 131366 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 131366 AND ge.slug = 'simulator' ON CONFLICT DO NOTHING;
