INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flatland: Fallen Angle', 'Inspired by a 19th Century novella, Flatland: Fallen Angle is the noir-esque tale of an isosceles triangle on the run from the law and hungry for revenge! Over ten astonishingly two-dimensional levels, the player must negotiate the various neighbourhoods of Polygonometropolis, and use their angles to slice, splinch and shatter anyone who gets in their way! The gameplay feels a little bit like Pacman, and the narrative approach is reminiscent of Bastion.but it all adds up to an absolutely unique short-form game experience!' FROM games WHERE igdb_id = 5609 ON CONFLICT (game_id, language_code) DO NOTHING;
