INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rurouni Kenshin: Meiji Kenkaku Romantan - Kansen', 'After the epic of Kyoto, Kenshin and his group settle back into their usual cycle of adventures. Old friends like Yutaro and Misao make appearances, as do villians like Shogo Amakusa, a rogue warrior who fights with the same sword style as Kenshin.' FROM games WHERE igdb_id = 44492 ON CONFLICT (game_id, language_code) DO NOTHING;
