INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('color-by-numbers-animals-plus', 86696, '2012-05-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/sokoj6hijx1s1en522qk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/qunucyklj3tjtpq0h0au.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Color by Numbers - Animals +', 'These amusing animals will lift your child’s spirits, and by coloring in the pictures your child will feel a real sense of accomplishment. Benefits:  ◦ Teaching children simple arithmetic. Addition and subtraction ◦ Coloring by geometrical figures and pictograms ◦ Coloring by letters ◦ Very simple program interface that any child can master  ◦ Easy-to-use palette that allows you to put together your own unique set of colors ◦ High-quality drawings of all pictures  ◦ Visual effects and sound effects  ◦ Pleasing background music  ◦ Colored pictures automatically saved on closing the program ◦ And many other useful features that make coloring entertaining Paint by numbers - an interactive coloring book for children. This mathematical game teaches children to recognize numbers and solve simple mathematical examples. In addition, this program develops memory, attention, imagination, and logical abilities. Boys and girls of all ages love to color. The simple coloring mode is suitable for the smallest of children, including those of kindergarten and preschool age. These include simple and recognizable images that are easy to color. If the child selects the wrong shape, then they will be prompted with the correct number. Therefore, the picture will always be colored correctly, and the child will quickly memorize the numbers. Children can choose to color by geometrical figures and pictograms in addition to numbers. A child can easily distinguish a square from a circle, diamond, and triangle. School-age children will enjoy the complex coloring mode. Here the picture is divided into a large number of elements, thus making it difficult at first to determine what it depicts. Older children can complicate the task by adding addition and subtraction tasks. Now children will need to solve the examples and choose the correct answers in order to color the picture. This will teach the child how to quickly do arithmetic in their mind. Those who are learning the alphabet can choose to color by letter. Coloring by letters will be useful for children preparing to enter primary school. To make the coloring process more interesting and fun, you can change any of the preset colors. To do this, press and hold the jar of paint and a palette will open. Then you can choose your favorite color. Thus, all the shaded areas of the image can be changed in the coloring by number mode. You can have fun by changing the color scheme to suit your taste. Try the program right now!' FROM games WHERE igdb_id = 86696 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 86696 AND p.igdb_id = 14 ON CONFLICT DO NOTHING;
