INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grooh', 'Grooh is a cute (and lazy?) monster that loves pineapples. Today, Grooh decides to explore the abandoned "Feilong Castle". There''s a huge dragon printed on the entrance door!! But most importantly, rumors say that there''s a secret treasure hidden there, and *who knows*, maybe it''s full of pineapples? That''s why you, oh mighty player, should help Grooh to find the treasure!' FROM games WHERE igdb_id = 197995 ON CONFLICT (game_id, language_code) DO NOTHING;
