INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kamikaze Pigs', 'A Flash-based, chain reaction game in where players must fry as many pigs as possible. The pigs are on edge and will fire at the first sign of trouble, causing further chaos and combos. Once the player gets enough money and stars, they can purchase upgrades in the shop to grant the pigs more guns and explosives to keep combos going.' FROM games WHERE igdb_id = 246157 ON CONFLICT (game_id, language_code) DO NOTHING;
