INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ys: Memories of Celceta - Silver Anniversary Edition', 'Ys: Memories of Celceta has players revisit the land and characters of the Japanese cult favorite Ys IV. This re-envisioning of the fourth installment in the Ys series takes a new approach, changing and framing the story of Ys IV within an all-new tale of conspiracy, deception and mystery. Silver Anniversary Edition includes a 3-Disc Soundtrack CD, Cloth Map Of Velceta, Branded Compass, Strategy & Art Book and collectors edition box.' FROM games WHERE igdb_id = 42679 ON CONFLICT (game_id, language_code) DO NOTHING;
