INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zooming Secretary', 'Part platformer, part puzzle, part workplace simulator and entirely satirical is what Zooming Secretary is. Playing the role of a secretary in her trial period at a new job, you have to work your way through an increasingly difficult week without being fired for failing to answer calls on time.' FROM games WHERE igdb_id = 48371 ON CONFLICT (game_id, language_code) DO NOTHING;
