INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wing Commander Saga: The Darkest Dawn', 'Wing Commander Saga: The Darkest Dawn concludes a forty-year galactic struggle between the Terran Confederation and the Kilrathi Empire, an imperialistic, xenophopic alien race. Victory and survival for humanity can only be bought at a terrible cost. Gather your wingmen and face the enemy. Make your mark as the Confederation faces its darkest dawn.' FROM games WHERE igdb_id = 19178 ON CONFLICT (game_id, language_code) DO NOTHING;
