INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'UEFA Euro 2012', 'The EA Sports UEFA Euro 2012 expansion pack for FIFA 12 recreates all the excitement of the official tournament with over 50 European national teams, all eight official stadiums, and all the pageantry and atmosphere of one of the largest and most-watched sporting events on the planet. Compete as your favorite country in an authentic online tournament mode against rival nations in the group stage, progress through the knockout rounds, and ultimately compete for the chance to be crowned the UEFA Euro 2012 champion. Plus, you will be able to relive dramatic moments from the UEFA Euro 2012 qualifying campaign with challenges based on real-life matches, and replay key moments from the UEFA Euro 2012 tournament.' FROM games WHERE igdb_id = 51328 ON CONFLICT (game_id, language_code) DO NOTHING;
