INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'iGun Pro', 'Ultra-Realistic gun simulation including both motion blur and smoke with an easy to learn interface let users quickly begin using their collection. iGun Pro has a massive library of specs, history, usage, and statistics of all the firearms featured in the app. Determine your shooting experience with adjustable recoil, motion blur, and slow motion.' FROM games WHERE igdb_id = 88473 ON CONFLICT (game_id, language_code) DO NOTHING;
