INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ano Ko wa Ore kara Hanarenai', 'Ano Ko wa Ore kara Hanarenai ("That Girl Can’t Separate Herself From Me") is a Japanese romantic visual novel. The player assumes the role of Hiroto, a Japanese high school student, whom many of the girls in his school take interest in. The Microsoft Windows version of the game is rated for adults only whilst the console releases are toned down.' FROM games WHERE igdb_id = 8640 ON CONFLICT (game_id, language_code) DO NOTHING;
