INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Touhou Mashousei: Fairies of Sorcery', 'Fairies of Sorcery is a fan-made Touhou Project script for the Touhou Danmakufu shooting game engine. Gameplay is based around the "burst" system, a limited-use skill which removes bullets on the screen and temporarily increases the value of point items. There are three stages in five difficulties plus an extra stage.' FROM games WHERE igdb_id = 280178 ON CONFLICT (game_id, language_code) DO NOTHING;
