INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Burger: The Tasty Burger Game', 'Want to be a master-chief? A burger-serving game is coming now for your best enjoyment in a free version with the Magma Mobile’s touch! You are hired in a chain restaurant to serve clients as fast as possible to earn money and even tips for yourself. Take orders from your customers and make a recipe among sandwiches, garnishes, desserts and sodas. The more you will play, the more ingredients will appear in the fast-food!' FROM games WHERE igdb_id = 87294 ON CONFLICT (game_id, language_code) DO NOTHING;
