INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Winx Club: Magical Fairy Party', 'Girls will embrace the magic within and discover their inner fairy in Winx Club: Magical Fairy Party, through the enchanting story and exciting mini-games filled with fairies, fashion, friendship (and pets) that fans love. Fans can star in the game as their own fairy, interact with their favorite show characters and enroll in the enchanting Alfea School. They will form new friendships, perform spells and plan unforgettable events that include a wondrous ball!' FROM games WHERE igdb_id = 25166 ON CONFLICT (game_id, language_code) DO NOTHING;
