INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Warhammer Online: Wrath of Heroes', 'Warhammer Online: Wrath of Heroes was a multiplayer online battle arena being developed by BioWare Mythic and supposed to be published by Electronic Arts for Microsoft Windows until it was canceled. The game was a spin-off based on Warhammer Online: Age of Reckoning and was a Play4Free title, Electronic Arts'' free-to-play model. The game did not progress beyond beta and was shut down on March 29, 2013 effectively canceling it.' FROM games WHERE igdb_id = 65721 ON CONFLICT (game_id, language_code) DO NOTHING;
