INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultima Ratio Regum', 'Ultima Ratio Regum ("the last argument of kings") is a game which aims to integrate thematic content on historiography, philosophical idealism and the rise of modernist grand narratives, with the deep, complex and challenging gameplay one expects from a "classic" roguelike (and, of course, an ANSI display and permadeath). Set approximately around the Scientific Revolution, the player is tasked with discovering a conspiracy via identifying procedurally-generated clues hidden throughout the world''s cultures, religions and societies; the game features extensive procedural generation of everything from tombs and religious altars to (in the future) paintings and sculptures, any or all of which may contain the clues required in a given playthrough.' FROM games WHERE igdb_id = 142341 ON CONFLICT (game_id, language_code) DO NOTHING;
