INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Forza Horizon: Limited Collector''s Edition', 'Combining the traditional Forza with a music festival vibe, Horizon promises to take freedom of the open road to the next level. Explore vast and varied driving playgrounds. Team up or compete with friends and rivals online. Show off your unique driving skills and become the star of the world''s most rocking motorsport party. Limited Collector''s Edition includes VIP Membership, VIP Car Pack, Day 1 Add-on Pack, Horizon Accelerator Token Pack, 5 Additional Car Pack Liveries and a limited edition Steelbook case.' FROM games WHERE igdb_id = 41594 ON CONFLICT (game_id, language_code) DO NOTHING;
