INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bad Piggies HD', 'An HD version of Bad Piggies, released on September 27, 2012, which was the same day that the regular version came out on iPhone and Android. It can be played on iPad and for the 2nd time also on Android but mainly for tablets. It became the only HD version to be on iPhone in 2020.' FROM games WHERE igdb_id = 221410 ON CONFLICT (game_id, language_code) DO NOTHING;
