INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-stacks', 40616, '2012-09-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5ynl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/tvontubjcvbp1gzure1b.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Stacks', 'Descending the networks of metal girders had always reminded me of old platform videogames like Donkey Kong or BurgerTime. I''d seized upon this idea a few years earlier when I coded my first Atari 2600 game (a gunter rite of passage, like a Jedi building his first lightsaber). It was a Pitfall rip-off called The Stacks where you had to navigate through a vertical maze of trailers, collecting junk computers, snagging food voucher power-ups, and avoiding meth addicts and pedophiles on your way to school. My game was a lot more fun than the real thing.' FROM games WHERE igdb_id = 40616 ON CONFLICT (game_id, language_code) DO NOTHING;
