INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hayate no Gotoku! CardBattlers', 'The player needs to collect cards of many characters from the Hayate no Gotoku! series, level up the character cards and do battle to gain ranks. Cards and items can be found during gameplay of the story, gashapon slot machine, trade, or participate in the events. The game uses a micro transaction payment model to allow the player who paid cash to gain an advantage over the free player.' FROM games WHERE igdb_id = 203999 ON CONFLICT (game_id, language_code) DO NOTHING;
