INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harmony''s Nightmare', 'Harmony''s Nightmare is a multi-genre homebrew Wii game about a young girl''s nightmares. The game is divided into 4 levels, each with a different play style. To beat the game you must collect at least 100 notes.' FROM games WHERE igdb_id = 281611 ON CONFLICT (game_id, language_code) DO NOTHING;
