INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gakuen Hetalia DS', 'Seychelles, a new student at World Academy W, winds up immediately involved in having to plan the school''s annual party, in which the students deepen their cultural exchanges and understanding of each other. To be able to pull off a successful party, Seychelles must plan carefully and get to know her classmates better.' FROM games WHERE igdb_id = 130581 ON CONFLICT (game_id, language_code) DO NOTHING;
