INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pac-Man Arcade Emulator', 'Despite the name, it''s not an emulated version of the arcade game. Rather, it''s a homebrew conversion of Pac-Man for the Amstrad CPC, in a way that tries to be the as arcade-perfect as it could with the CPC''s hardware limits.' FROM games WHERE igdb_id = 290264 ON CONFLICT (game_id, language_code) DO NOTHING;
