INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skater Boy', 'Skater Boy is a side-scrolling obstacle course with automatic scrolling. The game is divided into several scenes with 30 levels in each scene. The goal of each level is to simply reach the end of the course, however achievements are awarded for flawless skating, amassing a large number of points and getting all gold goblets. The skater boy is controlled by two on-screen buttons: the left one is used to accelerate, the right one to jump.' FROM games WHERE igdb_id = 191301 ON CONFLICT (game_id, language_code) DO NOTHING;
