INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gas Guzzlers: Combat Carnage', 'Gas Guzzlers: Combat Carnage is a fast-paced addictive combat racing game for the PC. The game features many different vehicles, weapons, upgrades, on-track bonuses as well as distinctive and astonishing environments. The player starts with a low-performance vehicle and gradually works his way up by earning money in a series of challenging races.With an initial amount of money,the player buys his first car without upgrades.' FROM games WHERE igdb_id = 29396 ON CONFLICT (game_id, language_code) DO NOTHING;
