INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flight Unlimited Las Vegas - Flight Simulator', 'Explore the city or embark on a campaign of missions for the Las Vegas Mob Boss. Over 130 sq miles of the city of Las Vegas are modeled in incredible detail. The famous Las Vegas strip includes over 50 hotels that are modeled with photo realism. Fly past the Luxor, buzz the New York New York, or attempt a landing on top of the Bellagio. Flight Unlimited also features street traffic, a first for a mobile flight simulator. Cars, trucks, and buses zoom around the city.' FROM games WHERE igdb_id = 93648 ON CONFLICT (game_id, language_code) DO NOTHING;
