INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('quest-for-the-golden-chalice', 306664, '2012-01-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8dzr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scsurn.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Quest for the Golden Chalice', 'Dragons and castles and bats... Oh my! The cowardly Prince of Larosia will need to face his deepest fears, as his kingdom has been overrun by a group of hungry dragons! Even worse, the evil mastermind behind this attack is none other than Mardok the wizard, who the Prince had banished a year before! The townspeople - including the royal guards - have all fled the kingdom, leaving the Prince alone to fend for himself, and even worse, Mardok has stolen the Golden Chalice, the greatest treasure of Larosia! It now falls to the Prince to restore the people''s confidence in his royalty, and there''s only one way to do it: He must return the Golden Chalice to the Yellow Castle! Guide the Prince as he runs across the kingdom, locating keys, a sword and other assorted objects, in an effort to locate the Golden Chalice and carry it back home. Don''t let the dragons get too close, or they will have the Prince for lunch! Also be wary of the giant bat, who will steal objects and move them around, causing the Prince additional headaches!' FROM games WHERE igdb_id = 306664 ON CONFLICT (game_id, language_code) DO NOTHING;
