INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Captain Cat', 'Captain Cat travels the seven seas in his boat, using his anchor as a hook to fish for the delights and treasures hiding at the bottom of the sea. But navigating the depths of unknown waters is never easy, there are many mysterious dangers to face along the way. Can Captain Cat overcome them to catch enough fish to satisfy his hunger?' FROM games WHERE igdb_id = 119294 ON CONFLICT (game_id, language_code) DO NOTHING;
