INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kingdom Conquest II', 'It is a time of war and chaos. Begin with nothing and end with a kingdom. SEGA’s Kingdom Conquest II is the epic free-to-play strategy game for conquerors.Dominate real players online. Unite the strong and crush the weak until final victory is declared. You decide who joins your cause or submits to your will. Kingdom Conquest II blends the best elements of card battling, real time strategy, MMORPGs, and 3D dungeon battles to deliver a massive and addictive fantasy war game like no other.' FROM games WHERE igdb_id = 51652 ON CONFLICT (game_id, language_code) DO NOTHING;
