INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Labyrinth no Kanata', 'Labyrinth no Kanata is a first-person RPG dungeon crawler for the Nintendo 3DS. The game was only released in Japan. The game revolves around a group of players who have begun playing an online multiplayer game, only to find themselves thrust into a world completely different from theirs. They encounter a girl who has become trapped in this world''s Labyrinth, and the two parties must work together to find a way out.' FROM games WHERE igdb_id = 6835 ON CONFLICT (game_id, language_code) DO NOTHING;
