INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kurohyou 2: Ryuu ga Gotoku Ashura-hen', 'Two years have passed ever since the Toda incident. Ukyo Tatsuya decides to live his life of growing stronger and stronger. However, Dragon Heat, the place where he fought his 10 battles, is being challenged by another underground fighting ring group called Ashura. Now Tatsuya must ally himself with some other young fighters in order to save Dragon Heat.' FROM games WHERE igdb_id = 121831 ON CONFLICT (game_id, language_code) DO NOTHING;
