INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Krunch', 'Krunch is a quick-reflex game about escaping, survival and the fear of being closed-in where you play as one of six Krons (mechanical orb-like entities) trapped in a seemingly abandoned fortress. Escape more than 100 claustrophobic levels spread across 4 zones, survive 3 challenging boss chases, conquer one frantic race to freedom! Krunch demands concentration, delivers fast gameplay and will test fans of games such as Mega Man, Super Meat Boy and VVVVVV.' FROM games WHERE igdb_id = 17104 ON CONFLICT (game_id, language_code) DO NOTHING;
