INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arc Style: Sangokushi Pinball', 'Arc Style: Sangokushi Pinball is a pinball game set during the Three Kingdoms period in ancient China. As well as a "Standard" mode where you progress through the stages, it includes a "Boss Attack" mode where you can go head-to-head with the mighty generals of the Three Kingdoms era who fought in "Standard", and "Library" where you can view information about unlocked events and warlords. High scores can be viewed in "Ranking" as well as an online leaderboard.' FROM games WHERE igdb_id = 222188 ON CONFLICT (game_id, language_code) DO NOTHING;
