INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Street Fighter 25th Anniversary Collector''s Set', 'Commemorating 25 years of one of the most popular videogame franchises of all time, the Street Fighter 25th Anniversary Collector''s Set is a must-have for Street Fighter aficionados. Created as a celebration and tribute to its fans, the limited edition set is individually numbered and jam-packed with Street Fighter games, video, art, music, and exclusive collectibles. The items are housed in a specially created chest complete with a certificate of authenticity.' FROM games WHERE igdb_id = 43011 ON CONFLICT (game_id, language_code) DO NOTHING;
