INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resident Evil Demake', 'Resident Evil Demake its like name says, the first Resident Evil made like running in a NES in 2D, the graphics and music have a 8bit style. The main mode with Jill is a shooter game, similar to the original game but in 2D. There''s new game modes like one for Chris with some RPG features. Many graphics are self-made, seeing the original game and making the sprites. I also made new music for some scenes.' FROM games WHERE igdb_id = 281816 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 281816 AND p.igdb_id = 6 ON CONFLICT DO NOTHING;
