INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Poptropica Adventures', 'The Poptropica museum is in ruins and needs your help! Explore three amazing islands and find missing artifacts to help restore the museum to its former glory. Meet interesting characters, collect artifacts, solve puzzles and play mini games in the ultimate on-the-go Poptropica experience!! Looking to stand out in a crowd? Customize the look of your avatar with new clothes, hats, hair styles and more and show off your own unique Poptropica style! Features: • Run and jump through three amazing Poptropica islands • Collect items and rebuild the Poptropica museum! • Complete the quests and unlock a host of minigames • Customize your avatar with new clothes, hats, hair styles and more' FROM games WHERE igdb_id = 47928 ON CONFLICT (game_id, language_code) DO NOTHING;
