INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stick Stunt Biker', 'Bike fun and challenging tracks using your destructible stick biker including jumps, loops, fire and other funny obstacles. Stick Stunt Biker is an agile and fast physic based bike game, with new updates every few weeks.' FROM games WHERE igdb_id = 289564 ON CONFLICT (game_id, language_code) DO NOTHING;
